/* Look up a standard by code, in either spelling. */
function CQ_code(raw) {
  const t = String(raw || '').trim().replace(/\s+/g, '');
  const direct = CQ_STANDARDS.standards[t];
  if (direct) return direct;
  // 3.4(H) -> 3.4H, and 3.9D (i) -> 3.9D (i)
  const flat = t.replace(/\(([A-Z])\)/g, '$1');
  return CQ_STANDARDS.standards[flat] || null;
}
